mapper.select:
SELECT d.id AS documentId, CASE WHEN d.title IS NULL OR CHAR_LENGTH(TRIM(d.title)) = 0 THEN CONCAT('作文 ', d.id) ELSE d.title END AS title, CASE WHEN d.task_prompt IS NULL OR CHAR_LENGTH(TRIM(d.task_prompt)) = 0 THEN 'free' ELSE 'exam' END AS mode, ds.latest_overall_score AS latestOverallScore, ds.best_overall_score AS bestOverallScore, COALESCE(e.word_count, ds.latest_word_count, 0) AS latestWordCount, COALESCE(e.total_error_count, ds.latest_total_error_count, 0) AS latestTotalErrorCount, e.created_at AS latestEvaluationAt FROM document_score_summary ds INNER JOIN documents d ON d.id = ds.document_id INNER JOIN essay_evaluation e ON e.id = ds.latest_evaluation_id WHERE ds.user_id = #{userId} AND d.owner_user_id = #{userId} AND d.deleted_at IS NULL AND ds.latest_evaluation_id IS NOT NULL AND e.overall_score IS NOT NULL
AND e.created_at >= #{startAt}
AND e.created_at < #{endExclusive}
AND ( #{mode} = 'all' OR ( #{mode} = 'free' AND (d.task_prompt IS NULL OR CHAR_LENGTH(TRIM(d.task_prompt)) = 0) ) OR ( #{mode} = 'exam' AND d.task_prompt IS NOT NULL AND CHAR_LENGTH(TRIM(d.task_prompt)) > 0 ) ) ORDER BY e.created_at ASC
